"""Summarize verified stage localization without inventing a specific code cause."""
import json,collections
from issue21_common import ROOT,save

def span(values):return [min(values),max(values)] if values else None
def main():
 c=json.loads((ROOT/'scientific_conclusion.json').read_text());pairs=json.loads((ROOT/'pair_analysis.json').read_text());perturb=json.loads((ROOT/'perturbation_analysis.json').read_text());air=[x for x in pairs if x['mode']=='air'];closed=[x for x in pairs if x['kind']=='closed'];triggers=json.loads((ROOT/'O_trigger_components.json').read_text());fields=['joint_pos','joint_vel','applied_torque','joint_target'];summary={'classification':c['classification'],'closed_initial_obs_global_max':max(x['metrics'][n]['step0_or1_linf'] for x in closed for n in ['ang_vel','gravity','commands','joint_pos_obs','joint_vel_obs','last_action','gait_phase']),'closed_initial_action_global_max':max(x['metrics']['action']['step0_or1_linf'] for x in closed),'exact_mirrored_input_actor_probe_max':max(x['counterfactual_action_error_max'] for x in closed),'air_first_step_ranges':{n:span([x['metrics'][n]['step0_or1_linf'] for x in air]) for n in fields},'air_contact_max':max(x['max_contact_force'] for x in air),'air_all200step_joint_target_max':max(x['metrics']['joint_target']['max_linf'] for x in air),'perturbation_seed_summaries':[]}
 seen=collections.defaultdict(set)
 for x in triggers:seen[(x['quantity'],x['component'])].add(x['case'])
 summary['most_repeated_O_components']=[{'quantity':n,'component':j,'paired_conditions_affected':len(cases)} for (n,j),cases in sorted(seen.items(),key=lambda x:(-len(x[1]),x[0]))[:12]]
 for ts in range(1,6):
  rows=[x for x in perturb if x['training_seed']==ts];summary['perturbation_seed_summaries'].append({'training_seed':ts,'baseline':rows[0]['baseline'],'perturbations':[{k:x[k] for k in ['epsilon','positive','negative','zero','censored','comparison_valid','flips','flip_fraction_valid']} for x in rows]})
 save('stage_interpretation.json',summary);p=ROOT/'results.md';s=p.read_text();marker='\n## Stage localization and perturbation interpretation\n';s=s.split(marker)[0];lines=[marker,'The complete five-seed evidence localizes the earliest observed deviation as follows:','', '- Initial closed-loop observation maximum component residual: %.9g; action residual: %.9g. Exact-transformed-input actor probe maximum: %.9g.'%(summary['closed_initial_obs_global_max'],summary['closed_initial_action_global_max'],summary['exact_mirrored_input_actor_probe_max']),'- Air/no-contact first-step residual ranges across all paired conditions: '+json.dumps(summary['air_first_step_ranges'])+'.','- Air maximum contact force: %.9gN; mirrored position-target error over all200 steps: %.9grad.'%(summary['air_contact_max'],summary['air_all200step_joint_target_max'])]
 if c['classification']=='O':lines+=['','These observations meet the frozen O rule. When the mirrored position targets are identical and contact forces are zero, the observed joint-state/active-force mismatch arises in the no-contact plant or its mirror coordinate contract, rather than requiring contact or a policy feedback difference. This does not isolate a defective source line or prove a particular PhysX, inertia or joint-frame cause. Static parameter symmetry alone cannot certify full nonlinear kinematic/drive/solver equivariance. The exact offending joint names, signs, environments and steps are reported above.']
 lines+=['','Perturbation comparison uses five separate cold unperturbed controls. Per training seed:','']
 for row in summary['perturbation_seed_summaries']:
  b=row['baseline'];cells='; '.join('eps%+.2f: +%d/-%d/zero%d/censored%d, flips%d of%d compared'%(x['epsilon'],x['positive'],x['negative'],x['zero'],x['censored'],x['flips'],x['comparison_valid']) for x in row['perturbations']);lines.append('- Seed%d baseline +%d/-%d, censored%d: %s.'%(row['training_seed'],b['positive'],b['negative'],b['censored'],cells))
 lines+=['','These are empirical sign changes within the prescribed perturbation range, not a proof of the global number of attractors. O takes precedence over N/H under the frozen rules; the perturbation data does not override the detected no-contact failure. No corrective training or default change is implemented. The single next-step recommendation remains the one stated at the beginning of this report.']
 p.write_text(s+'\n'.join(lines)+'\n');print('ISSUE21_STAGE_INTERPRETATION_WRITTEN',c['classification'],flush=True)
if __name__=='__main__':main()
